(function() {
  var overlayEl = null;

  function getXPath(el) {
    var parts = [];
    var node = el;
    while (node && node.nodeType === 1) {
      var idx = 1;
      var sib = node.previousElementSibling;
      while (sib) {
        if (sib.tagName === node.tagName) idx++;
        sib = sib.previousElementSibling;
      }
      parts.unshift(node.tagName.toLowerCase() + '[' + idx + ']');
      node = node.parentElement;
    }
    return '/' + parts.join('/');
  }

  function removeOverlay() {
    if (overlayEl && overlayEl.parentNode) {
      overlayEl.parentNode.removeChild(overlayEl);
      overlayEl = null;
    }
  }

  function drawOverlay(el) {
    removeOverlay();
    var rect = el.getBoundingClientRect();
    var scrollTop = window.scrollY || document.documentElement.scrollTop;
    var scrollLeft = window.scrollX || document.documentElement.scrollLeft;
    overlayEl = document.createElement('div');
    overlayEl.id = '__notifal_builder_overlay__';
    overlayEl.style.cssText = [
      'position:absolute',
      'pointer-events:none',
      'z-index:99999',
      'box-sizing:border-box',
      'outline:2px solid ${Sp}',
      'outline-offset:1px',
      'background:rgba(126,43,210,0.06)',
      'border-radius:3px',
      'transition:all 80ms ease',
      'top:' + (rect.top + scrollTop) + 'px',
      'left:' + (rect.left + scrollLeft) + 'px',
      'width:' + rect.width + 'px',
      'height:' + rect.height + 'px',
    ].join(';');
    document.body.appendChild(overlayEl);
  }

  document.addEventListener('click', function(e) {
    var el = e.target;
    if (!el || el.id === '__notifal_builder_overlay__') return;
    e.preventDefault();
    e.stopPropagation();
    var xpath = getXPath(el);
    drawOverlay(el);
    window.parent.postMessage({ type: 'NOTIFAL_BUILDER_SELECT', xpath: xpath }, '*');
  }, true);

  window.addEventListener('message', function(e) {
    if (e.data && e.data.type === 'NOTIFAL_BUILDER_DESELECT') {
      removeOverlay();
    }
    if (e.data && e.data.type === 'NOTIFAL_BUILDER_HIGHLIGHT' && e.data.xpath) {
      var result = document.evaluate(
        e.data.xpath, document, null,
        XPathResult.FIRST_ORDERED_NODE_TYPE, null
      );
      var node = result.singleNodeValue;
      if (node) {
        drawOverlay(node);
        node.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    }
  });

  document.addEventListener('click', function(e) {
    var el = e.target;
    while (el) {
      if (el.tagName === 'A') { e.preventDefault(); break; }
      el = el.parentElement;
    }
  });
})();
